me – Offering (Onboarding) 2025"], "estado": "adaptar"}, {"id": "REP", "nombre": "Reporting", "horizontales": ["Regulatorio", "Granular", "Sostenibilidad", "Financiero"], "rfp": "RFP Reporting (a nombrar)", "fundamentos": "FINREP / COREP, Pilar III, plantillas IRRBB, BCBS 239 y RDA, reporting granular, reporting de sostenibilidad (CSRD, Pilar III ESG), trazabilidad y consistencia.", "regulacion": "Paquete EBA de reporting, Pilar III ESG y GAR, CSRD / ESRS, data-ready para supervisor.", "oferta": "Granular Reporting Tool, reporting centralizado, Banco 360, ESG reporting suite, controles de consistencia apoyados en IA.", "metodos": "Modelo de datos de reporting, reconciliaciones, automatización de plantillas.", "certificacion": "A definir por el RFP.", "material": ["ESG reporting suite (interno)"], "estado": "crear"}, {"id": "ANA", "nombre": "Analytics, Data e IA", "horizontales": ["Data", "IA aplicada", "Gobierno del dato"], "rfp": "RFP Analytics (a nombrar)", "fundamentos": "Gobierno del dato y data quality, modelado (Single Data Model), analítica y modelos predictivos, IA generativa y agentes, MLOps, casos de uso por práctica (fraude, scoring, FP&A, actas).", "regulacion": "AI Act, GDPR y datos de cliente, gobierno de modelos, BCBS 239.", "oferta": "PoCs de IA (4 por trimestre en el plan FY25), NChat / Gemini, agentes con Claude, stack interno Supabase + Vercel, Credentials IQ.", "metodos": "SQL y Python, prompting y agentes, evaluación de modelos, pipelines de datos.", "certificacion": "AWS / Azure / GCP (data o ML); PSM / PSPO para entrega ágil.", "material": ["Welcome Pack DaaP y DPM CIB (BBVA)", "Propuesta incorporación IA proyecto LIFE (2026)"], "estado": "adaptar"}]}$j$::jsonb),
