ontenido": ["Contenido específico de cada práctica (campo «oferta» de la ficha)."]}, {"id": "P-04", "nombre": "Métodos, modelos y herramientas", "horas": 10, "aplica": {"J": "obl", "S": "obl", "M": null, "D": null}, "eventos": ["alta", "cambio_practica"], "objetivo": "Hacer el trabajo: metodologías, modelos, plantillas y herramientas del ámbito.", "formato": "Labs prácticos", "bloque": "In-house · curso de negocio", "canal": "Classroom", "evaluacion": "Entregable práctico", "responsable": ["RFP", "COL"], "momento": "Trimestres 1–2", "capa": "Práctica", "contenido": ["Contenido específico de cada práctica (campo «metodos» de la ficha)."]}, {"id": "P-05", "nombre": "Certificación de la práctica", "horas": 0, "horasExternas": "100–300 h externas", "aplica": {"J": "rec", "S": "rec", "M": "ele", "D": null}, "eventos": ["alta", "cambio_practica"], "objetivo": "Acreditar el conocimiento con la certificación que la práctica reconoce.", "formato": "Autoestudio + examen externo", "bloque": "Externo · Certificaciones del catálogo / PEBF", "canal": "Formulario de certificaciones + visto bueno del mentor", "evaluacion": "Certificado (reembolso 100 % con permanencia)", "responsable": ["MEN", "RF"], "momento": "Años 1–2", "capa": "Práctica", "contenido": ["Contenido específico de cada práctica (campo «certificacion» de la ficha)."]}, {"id": "P-06", "nombre": "Comunidad de práctica", "horas": 10, "aplica": {"J": "obl", "S": "obl", "M": "obl", "D": "obl"}, "eventos": ["alta", "cambio_practica", "anual"], "objetivo": "Compartir lo aprendido en proyectos y mantener vivas las credenciales.", "formato": "Sesión mensual", "bloque": "In-house", "canal": "Sesión", "evaluacion": "Asistencia", "responsable": ["RFP"], "momento": "Mensual", "capa": "Práctica", "contenido": ["Sesión mensual de 1 h", "Lecciones de proyectos cerrados (PR-04)", "Novedades regulatorias y de mercado (observatorio)", "Nuevas credenciales y materiales de venta"]}, {"id": "P-07", "nombre": "Liderar la práctica", "horas": 6, "aplica": {"J": null, "S": null, "M": "obl", "D": "obl"}, "eventos": ["promocion", "anual"], "objetivo": "Dirigir la capacidad: propuesta de valor, plan trimestral de capacidades, staffing y formación de perfiles.", "formato": "Taller anual", "bloque": "In-house", "canal": "Sesión", "evaluacion": "Plan de capacidades entregado", "responsable": ["RFP", "RUN"], "momento": "Anual / al promocionar", "capa": "Práctica", "contenido": ["Propuesta de valor y materiales de venta del ámbito", "Plan de capacidades trimestral (modelo interlock) y presupuesto", "Staffing, cross-support y formación de perfiles en ámbitos incipientes", "Cross-selling con los cuadrantes de cliente"]}], "Proyecto": [{"id": "PR-01", "nombre": "Kick-off del proyecto", "horas": 2, "aplica": {"J": "obl", "S": "obl", "M": "obl", "D": "obl"}, "eventos": ["alta", "cambio_ug"], "objetivo": "Contexto, alcance, equipo, interlocutores y SLAs antes de la primera tarea.", "contenido": ["Por qué existe el proyecto y qué se ha vendido", "Equipo, roles y calendario", "Interlocutores del cliente", "Compromisos: SLAs, prioridades, penalizaciones"], "formato": "Sesión del manager", "bloque": "In-house · plan de proyecto", "canal": "Sesión", "evaluacion": "Ninguna", "responsable": ["MGR"], "momento": "Día 1 en el proyecto", "material": ["ANS_FX_Plan_Formacion (modelo)"], "estado": "adaptar", "capa": "Proyecto", "tpl": "PR-01"}, {"id": "PR-02", "nombre": "Herramientas y entornos del proyecto", "horas": 4, "aplica": {"J": "obl", "S": "obl", "M": "obl", "D": "obl"}, "eventos": ["alta", "cambio_ug"], "objetivo": "Acceder y operar las herramientas concretas del proyecto.", "contenido": ["Entornos, repositorios y accesos", "Herramientas de ticketing, monitorización y datos", "Documentación y carpetas de traspaso"], "formato": "Self-service + sesiones cortas", "bloque": "In-house · plan de proyecto", "canal": "Drive del proyecto", "evaluacion": "Checklist", "responsable": ["MGR"], "momento": "Semana 1 en el proyecto", "material": ["Documento bienvenida V2.0 (modelo)"], "estado": "adaptar", "capa": "Proyecto", "tpl": "PR-02"}, {"id": "PR-03", "nombre": "Operativa y calidad del proyecto", "horas": 4, "aplica": {"J": "obl", "S": "obl", "M": "rec", "D": null}, "eventos": ["alta", "cambio_ug"], "objetivo": "Trabajar con el procedimiento del proyecto: escalado, análisis de causa raíz, entregables.", "contenido": ["Procedimientos y flujos", "Escalado, war rooms, guardias", "Análisis de causa raíz y troubleshooting", "Criterios de calidad de los entregables"], "formato": "Sesiones + shadowing", "bloque": "In-house · plan de proyecto", "canal": "Sesión", "evaluacion": "Caso práctico", "responsable": ["MGR"], "momento": "Semanas 1–3 en el proyecto", "material": ["ANS_FX_Plan_Formacion (modelo)"], "estado": "adaptar", "capa": "Proyecto", "tpl": "PR-03"}, {"id": "PR-04", "nombre": "Cierre: lecciones y credencial", "horas": 1, "aplica": {"J": "obl", "S": "obl", "M": "obl", "D": "obl"}, "eventos": ["anual"], "objetivo": "Convertir cada proyecto en conocimiento de firma: lección aprendida y credencial.", "contenido": ["Qué funcionó y qué no", "Ficha de credencial (Credentials IQ)", "Qué se lleva a la comunidad de práctica"], "formato": "Sesión de cierre", "bloque": "In-house", "canal": "Sesión", "evaluacion": "Ficha de credencial entregada", "responsable": ["MGR", "RFP"], "momento": "Al cerrar el proyecto", "material": [], "estado": "crear", "capa": "Proyecto", "tpl": "PR-04"}]}$j$::jsonb),
  ('reglas', 'ALL', $j${"items": ["Toda persona tiene un cuadrante de cliente, una práctica principal y, si procede, una secundaria. La secundaria solo añade P-01, P-03 y P-06.", "Nueva incorporación: Firma (semana New Joiners) + Cliente + Práctica + Proyecto. Cambio de cuadrante: solo Cliente y Proyecto. Cambio de práctica: solo Práctica.", "Promoción: la banda de destino abre F-10 (Manager), F-11 y F-12 (Senior), C-05 y P-07 (Manager y Dirección).", "Senior convalida P-01 y P-04 con test de nivel; Manager y Dirección no los cursan salvo cambio de práctica.", "Obligatorio es obligatorio: sin él no se cierra la evaluación del periodo. Recomendado lo decide el mentor. Electivo lo pide la persona.", "Un módulo sin dueño nominal no entra en el catálogo. El dueño mantiene el material y nombra formadores.", "Completado = asistencia + test (in-house) o certificado (externo). La evidencia queda en la app y se ve desde Career.", "Cada proyecto cerrado deja una lección y una credencial (PR-04); la comunidad de práctica (P-06) las recoge."]}$j$::jsonb),
  ('integracion', 'ALL', $j${"items": [{"sgc": "Plan Estratégico (trienal) y Plan Táctico (anual)", "como": "El catálogo es el Plan Táctico expresado por perfil. Cada año se revisa la lista de módulos, horas y dueños; la ruta de cada persona se recalcula sola."}, {"sgc": "Cursos cross y cursos de negocio", "como": "Cursos cross = capa Firma. Cursos de negocio = capas Cliente y Práctica. Misma distinción, ahora con nombre."}, {"sgc": "Selección de asistentes (mentores, RUN, responsables de cliente)", "como": "El perfil (cuadrante, práctica, banda, situación) propone la lista; el mentor valida y Formación convoca. Deja de depender de que alguien se acuerde."}, {"sgc": "Roles RF, RFUN, RUN, RC&T, MEN, COL", "como": "Se mantienen. Un solo rol nuevo: RFP, responsable de formación de la práctica, espejo del RFUN para el eje de prácticas."}, {"sgc": "Formación in-house: material, formadores, PoC, test", "como": "Todo módulo in-house sigue ese flujo. Los que marcamos como «existe» ya tienen material; «adaptar» tiene material parcial; «crear» entra en el plan táctico del año."}, {"sgc": "Idiomas, PEBF Comillas, soft skills Thinkium, certificaciones, a demanda", "como": "Entran como módulos F-08, P-05 y F-07 sin cambiar sus reglas (convocatorias, penalizaciones, reembolsos)."}, {"sgc": "Objetivo 40 h/empleado/año", "como": "El simulador suma las horas de la ruta y las compara con 40. El año de incorporación supera el objetivo por diseño; el régimen debe quedar cerca."}, {"sgc": "Registros: Campus Nfq, Nation, My.NFQ, Skynet, Classroom", "como": "Classroom sigue siendo el canal de impartición; la app registra perfil, ruta, estado y evidencia y los liga a Career y Evaluations en My.NFQ."}, {"sgc": "Semana New Joiners y PRL", "como": "Son el módulo de onboarding de la app (F-01 a F-06 y F-09). No se crea otro onboarding."}]}$j$::jsonb),
  ('defaults', 'ALL', $j${"alcance": "Advisory (≈756 FTE); estructura extensible a Tech & Data, Ops y Soluciones", "cuadrantes": "7 según la lista de dirección; UG01 Santander y UG02 BBVA confirmados, el resto de códigos UG por confirmar", "practicas": "9 ámbitos de la Estrategia Advisory FY25-27; horizontales GTB→Banca mayorista, ALM→Finanzas, ESG→Sostenibilidad, Data→Analytics", "bandas": "4 bandas sobre 8 categorías (ASSI, CONS, CNSR, EXPR, Manager, Senior Manager, Director, Partner); confirmar en Nfolks", "pertenencia": "1 cuadrante + 1 práctica principal + 1 secundaria opcional"}$j$::jsonb),
  ('version', 'ALL', $j${"version": "v0 · 20/10/2026"}$j$::jsonb)
